CREATE TABLE reject (order_id integer, reason text, amount_cents integer);
INSERT INTO reject VALUES (1005, 'unknown customer', 1000), (1002, 'duplicate order', 30000), (1006, 'missing amount', NULL), (1007, 'unknown customer', 250);
SELECT reason, count(*) AS n, coalesce(sum(amount_cents), 0) AS cents
FROM reject GROUP BY reason ORDER BY reason;
